package com.mieai.qqbot.runtime.supervisor
import java.time.Instant
data class BotRuntimeSummary(val configuredBots:Int,val enabledBots:Int,val runningBots:Int,val onlineBots:Int,val reconnectingBots:Int,val failedBots:Int,val observedAt:Instant) { init { require(listOf(configuredBots,enabledBots,runningBots,onlineBots,reconnectingBots,failedBots).all{it>=0}) }; companion object { internal fun from(statuses:List<BotRuntimeStatus>,observedAt:Instant):BotRuntimeSummary { var e=0;var r=0;var o=0;var rc=0;var f=0; statuses.forEach{if(it.desiredEnabled)e++;if(it.state.isRunning())r++;if(it.state==BotRuntimeState.ONLINE)o++;if(it.state==BotRuntimeState.RECONNECTING)rc++;if(it.state==BotRuntimeState.FAILED)f++}; return BotRuntimeSummary(statuses.size,e,r,o,rc,f,observedAt) } } }
